def daily_cap(first_send_str):
    if not first_send_str: return 8
    days = (date.today() - date.fromisoformat(first_send_str)).days
    return 8 if days < 7 else (15 if days < 14 else 25)

# ─── AgentMail ────────────────────────────────────────────────────────────────
def _parse_am_keys(raw):
    out = {}
    for i, m in enumerate(re.finditer(r"(?:[A-Za-z0-9_.@-]+=)?(am_[A-Za-z0-9_\-.]+)", raw)):
        label = (m.group(0).split("=")[0] if "=" in m.group(0) and not m.group(0).startswith("am_") else f"k{i+1}")
        while label in out: label += "_"
        out[label] = m.group(0).split("=")[-1]
    return out

class RampLimited(RuntimeError):
    """AgentMail per-ORGANIZATION recipient ramp (429 rate_limit_exceeded with
    "Recipient limit exceeded ... The limit lifts at <ISO>"). Free-plan orgs may
    email only 25 distinct recipients in their first week (10 after an agent
    verification / ramp restart). This is NOT transient -- retrying every lead
    3x with a 6s sleep (the old behaviour) burned ~400 doomed API calls a day.
    The whole org is parked until the lift time, persisted in org_blocks.json."""
    def __init__(self, msg, lift_iso):
        super().__init__(msg)
        self.lift_iso = lift_iso

_LIFT_RE = re.compile(r"lifts at (\d{4}-\d\d-\d\dT[\d:.]+Z)")

def http_json(url, method="GET", body=None, headers=None):
    data = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=data, method=method, headers=headers or {})
    last = ""
    for attempt in range(4):
        try:
            with urllib.request.urlopen(req, context=CTX, timeout=30) as r:
                txt = r.read().decode()
                return json.loads(txt) if txt.strip() else {}
        except urllib.error.HTTPError as e:
            txt = e.read().decode()[:600]
            if e.code == 429:
                low = txt.lower()
                if "recipient limit" in low or "sending ramp" in low:
                    m = _LIFT_RE.search(txt)
                    lift = m.group(1) if m else None
                    if not lift:
                        try: ra = float(e.headers.get("Retry-After") or 0)
                        except Exception: ra = 0
                        lift = (datetime.now(timezone.utc) + timedelta(seconds=ra or 86400)).isoformat()
                    raise RampLimited(f"429 org ramp limit: {txt[:220]}", lift)
                # ordinary API rate limit: honour Retry-After with exponential backoff
                try: ra = float(e.headers.get("Retry-After") or 1)
                except Exception: ra = 1
                last = txt
                time.sleep(min(60, max(1.0, ra) * (2 ** attempt)))
                continue
            raise RuntimeError(f"HTTP {e.code} {method} {url}: {txt[:300]}")
    raise RuntimeError(f"retries exhausted (429): {last[:200]}")

def _parse_iso(s):
    try:
        return datetime.fromisoformat(str(s).replace("Z", "+00:00"))
    except Exception:
        return datetime.now(timezone.utc)

def am_call(key, method, path, body=None):
    return http_json(AM_BASE + path, method, body,
        {"Authorization": f"Bearer {key}", "Content-Type": "application/json"})

def build_am_inboxes(keys_dict):
    imap = {}
    for label, k in keys_dict.items():
        try:
            inboxes = am_call(k, "GET", "/inboxes?limit=100").get("inboxes", [])
            for ib in inboxes:
                # AgentMail's API actually returns snake_case "inbox_id" --
                # the previous code only checked camelCase "inboxId", which
                # never matched, silently producing em="" and skipping every
                # real inbox (hence "AM inboxes: 0" on every run despite
                # valid keys and a successful API call with no exception).
                em = (ib.get("inbox_id") or ib.get("inboxId") or ib.get("email") or "").lower()
                org = ib.get("organization_id") or ib.get("organizationId") or ""
                if em: imap[em] = (label, k, org)
                else: print(f"  WARN AM {label}: inbox with no recognizable id field: {ib}", file=sys.stderr)
        except Exception as e:
            print(f"  WARN AM {label}: {e}", file=sys.stderr)
    return imap

# ─── GWS JWT (pure stdlib) ────────────────────────────────────────────────────
def _b64url(data):
    if isinstance(data, str): data = data.encode()
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()

def _gws_access_token(info, subject, scopes):
    """Get OAuth2 access token for a service account via JWT. stdlib only."""
    import time as _t
    now = int(_t.time())
    header = _b64url(json.dumps({"alg":"RS256","typ":"JWT"}))
    claim  = _b64url(json.dumps({
        "iss": info["client_email"], "sub": subject,
        "scope": " ".join(scopes), "aud": info["token_uri"],
        "iat": now, "exp": now + 3600
    }))
    signing_input = f"{header}.{claim}".encode()

    # Sign with RSA-SHA256 using cryptography or rsa package if available, else try subprocess
    try:
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        pem = info["private_key"].encode()
        private_key = serialization.load_pem_private_key(pem, password=None)
        sig = private_key.sign(signing_input, padding.PKCS1v15(), hashes.SHA256())
        jwt = f"{header}.{claim}.{_b64url(sig)}"
    except ImportError:
        # Try openssl subprocess
        import subprocess, tempfile, os
        with tempfile.NamedTemporaryFile(suffix=".pem", delete=False, mode="w") as f:
            f.write(info["private_key"]); fname = f.name
        try:
            proc = subprocess.run(
                ["openssl", "dgst", "-sha256", "-sign", fname, "-"],
                input=signing_input, capture_output=True)
            if proc.returncode: raise RuntimeError(f"openssl failed: {proc.stderr}")
            jwt = f"{header}.{claim}.{_b64url(proc.stdout)}"
        finally:
            os.unlink(fname)

    # NOTE: a prior version of this function made a first request here via
    # http_json() passing a dict body -- which http_json() JSON-encodes --
    # while declaring Content-Type: application/x-www-form-urlencoded. Google
    # parsed that as form data, found no real grant_type, and rejected every
    # single call with 400 "unsupported_grant_type: Invalid grant_type: "
    # before the correctly form-encoded request below ever ran. That dead,
    # always-failing call has been removed.
    form = f"grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion={jwt}"
    req2 = urllib.request.Request(info["token_uri"],
        data=form.encode(), method="POST",
        headers={"Content-Type": "application/x-www-form-urlencoded"})
    with urllib.request.urlopen(req2, context=CTX, timeout=20) as r:
        token_resp = json.loads(r.read().decode())
    return token_resp["access_token"]

def send_via_gws(info, sender_email, sender_name, to_email, subject, html_body, text_body, extra_headers=None, thread_id=None):
    token = _gws_access_token(info, sender_email,
        ["https://www.googleapis.com/auth/gmail.send"])
    msg = EmailMessage()
    msg["From"] = formataddr((sender_name, sender_email))
    msg["To"] = to_email
    msg["Subject"] = subject
    msg["Date"] = formatdate(localtime=True)
    msg["Message-ID"] = make_msgid(domain=sender_email.split("@")[1])
    msg["Reply-To"] = sender_email
    msg["List-Unsubscribe"] = f"<mailto:{sender_email}?subject=remove>"
    for _k, _v in (extra_headers or {}).items():
        if _v: msg[_k] = _v
    msg.set_content(text_body)
    msg.add_alternative(html_body, subtype="html")
    raw = base64.urlsafe_b64encode(msg.as_bytes()).decode()
    result = http_json(
        f"https://gmail.googleapis.com/gmail/v1/users/me/messages/send",
        "POST", ({"raw": raw, "threadId": thread_id} if thread_id else {"raw": raw}),
        {"Authorization": f"Bearer {token}", "Content-Type": "application/json"})
    return result.get("threadId", "")

def _parse_gws_key(raw):
    s = raw.strip()
    for cand in (s, "{" + s + "}"):
        try:
            d = json.loads(cand)
            if isinstance(d, dict) and d.get("private_key"): return d
        except: pass
    pairs = re.findall(r'([a-z0-9_]+)\t("(?:[^"\\]|\\.)*")', s)
    d = {k: json.loads(v) for k, v in pairs}
    return d if d.get("private_key") else None

