def _fmt_closes(raw):
    # Supabase returns timestamptz ("2026-10-12T09:00:00+00:00"); the previous
    # code did raw[:6], which rendered the chip as "Closes 2026-1" in every
    # live email. Format as "12 Oct" to match the FALLBACK style.
    try:
        d = date.fromisoformat(str(raw)[:10])
        return f"{d.day} {d.strftime('%b')}"
    except Exception:
        return str(raw)[:10]

