_PLACE_RE = re.compile(r"\b(" + "|".join(r"\s+".join(re.escape(w) for w in p.split()) for p in _PLACES) + r")\b", re.I)
_PLACE_MAP = {" ".join(p.lower().split()): p for p in _PLACES}
_ALWAYS_RE = re.compile(r"\b(" + "|".join(_ALWAYS) + r")\b", re.I)
_RX_REF  = re.compile(r"^ref(erence)?\b(\s*(no\.?|number))?\s*[:.#]?\s+([A-Z]{2,6}\s+)?[A-Z0-9][\w/.\-]*\d[\w/.\-]*(\s+\d+)?\s*[:\-]?\s+", re.I)
_RX_RFX  = re.compile(r"^(request for (quotations?|proposals?|bids?)|invitation to (bid|quote))\s*(\((rfq|rfp|rfb)\))?\s*:?\s*(for\s+)?", re.I)
_RX_RFX2 = re.compile(r"^(rfq|rfp|rfb)\s*[:\-]\s*", re.I)
_RX_APPT = re.compile(r"^(the\s+)?appointment of (an?\s+)?((suitabl[ey]|qualified|competent|experienced|accredited|reputable|capable|professional|panel of|and|&)[,\s]+)*(service providers?(/s)?|contractors?|suppliers?|companies|consultants?)\s+(for|to)\s+(the\s+)?(provision of\s+|provide\s+|render\s+|supply\s+)?(an?\s+)?", re.I)
_RX_PROV = re.compile(r"^(for\s+)?the\s+provision(ing)?\s+of\s+", re.I)
_RX_RFAP = re.compile(r"^request for\s*(\((rfq|rfp|rfb)\))?\s*(of|for)\s+(an?\s+)?appointment of\s+(\w+\s+\(\d+\)\s+)?(service providers?|contractors?|suppliers?)\s+(for|to)\s+(the\s+)?(provision of\s+)?", re.I)

def tidy_title(raw, mx=95):
    """eTenders titles arrive as 'REQUEST FOR QUOTATION (RFQ): APPOINTMENT OF A SERVICE PROVIDER FOR THE PROVISION OF ...'.
    Same rules as lib/titles.js: drop procurement boilerplate, sentence-case shouting, restore acronyms and place names,
    cut on a word boundary (the old code cut raw ALL-CAPS titles at 100 characters, mid-word)."""
    t = " ".join(str(raw or "").split())
    letters = re.sub(r"[^A-Za-z]", "", t)
    shouting = len(letters) > 8 and len(re.sub(r"[^A-Z]", "", letters)) / len(letters) > 0.6
    for rx in (_RX_REF, _RX_RFAP, _RX_RFX, _RX_RFX2, _RX_APPT, _RX_PROV): t = rx.sub("", t, count=1)
    t = re.sub(r"[.\s]+$", "", t)
    if shouting:
        t = re.sub(r"\b([a-z0-9]{2,6})\b", lambda m: m.group(1).upper() if m.group(1).upper() in _ACR else m.group(1), t.lower())
    t = _PLACE_RE.sub(lambda m: _PLACE_MAP.get(" ".join(m.group(0).lower().split()), m.group(0)), t)
    t = _ALWAYS_RE.sub(lambda m: m.group(0).upper(), t)
    t = t[:1].upper() + t[1:]
    if len(t) > mx: t = re.sub(r"\s+\S*$", "", t[:mx - 2]).rstrip(",;:-") + "…"
    return t

def tidy_buyer(n):
    t = " ".join(str(n or "").split())
    if not t or t != t.upper(): return t
    out = []
    for i, w in enumerate(t.split()):
        core = re.sub(r"[^A-Za-z0-9]", "", w)
        if core in _ACR or core in {"CC", "JV", "NPC", "SOC"}: out.append(w)
        elif core in {"AND", "OF", "THE", "FOR"} and i: out.append(w.lower())
        else: out.append(w[:1] + w[1:].lower())
    return " ".join(out)

def _closes_date(s):
    try:
        d = datetime.strptime(f"{s} {date.today().year}", "%d %b %Y").date()
        return d + timedelta(days=0) if (date.today() - d).days <= 180 else d.replace(year=d.year + 1)
    except Exception:
        return None

def _fresh(rows, min_days=4):
    """The live query already requires closes >= today+4. The hard-coded FALLBACK never expired: a lead whose trade had no
    live rows was emailed tenders that had already closed."""
    cut = date.today() + timedelta(days=min_days)
    return [r for r in rows if (_closes_date(r[2]) or date.min) >= cut]

