def _title_cond(kw):
    if "|" in kw:
        return "or=(" + ",".join(f"title.ilike.*{urllib.request.quote(t)}*" for t in kw.split("|") if t) + ")"
    return f"title=ilike.*{urllib.request.quote(kw.split()[0])}*"

COUNTS = {}   # trade -> open tenders nationally (capped at the query limit)

def fetch_tenders():
    live = {}
    if SUPA_URL and SUPA_KEY:
        today4 = (date.today() + timedelta(days=4)).isoformat()
        hdr = {"apikey": SUPA_KEY, "Authorization": f"Bearer {SUPA_KEY}"}
        base = f"{SUPA_URL}/rest/v1/vula_tenders?select=ocid,title,buyer,closes&province=ilike.*gauteng*&closes=gte.{today4}&jev_scam_flag=neq.true"
        base_nat = f"{SUPA_URL}/rest/v1/vula_tenders?select=ocid,title,buyer,closes,province&closes=gte.{today4}&jev_scam_flag=neq.true"
        for trade, kw in TRADE_KW.items():
            jev_rows, kw_rows = [], []
            if trade in NOUNS and trade[:1].isupper():          # standard trades: the feed's own classification, best worth score first
                try:
                    jev_rows = http_json(f"{base}&jev_trade=eq.{urllib.request.quote(trade)}&order=jev_worth_score.desc.nullslast,closes.asc&limit=4", headers=hdr) or []
                except Exception: pass
            try:                                                  # title keywords (previous behaviour), soonest closing first
                kw_rows = http_json(f"{base}&{_title_cond(kw)}&order=closes.asc&limit=8", headers=hdr) or []
            except Exception: pass
            # One best-worth Jev pick, then keyword hits (soonest closing), then more Jev picks only to fill gaps. Letting Jev fill
            # first crowded out clearly relevant keyword hits (e.g. a guarding tender for a security company).
            order = jev_rows[:1] + kw_rows + jev_rows[1:]
            seen, picked = set(), []
            for r in order:
                # belt and braces: a "Regret Letter" / cancellation notice is NOT an open tender
                if not r.get("ocid") or r["ocid"] in seen or re.search(r"regret|cancel", r.get("title", ""), re.I): continue
                seen.add(r["ocid"]); picked.append(r)
            picked = sorted(picked[:4], key=lambda r: r["closes"])
            rows_out = [(tidy_title(r["title"]), tidy_buyer(r["buyer"]), _fmt_closes(r["closes"]), r["ocid"]) for r in picked]
            # 2026-10-20: one tender is not an offer. Top up to five with the soonest-closing tenders from the rest of the country
            # (province shown on the row) and remember how many are open nationally, so the email can say "37 open" not "one".
            try:
                nat = http_json(f"{base_nat}&{_title_cond(kw)}&order=closes.asc&limit=40", headers=hdr) or []
            except Exception:
                nat = []
            nat = [r for r in nat if r.get("ocid") and not re.search(r"regret|cancel", r.get("title", ""), re.I)]
            COUNTS[trade] = max(len(nat), len(picked))
            have = {r["ocid"] for r in picked}
            for r in nat:
                if len(rows_out) >= 5: break
                if r["ocid"] in have: continue
                prov = (r.get("province") or "").strip()
                rows_out.append((tidy_title(r["title"]), tidy_buyer(r["buyer"]) + (f" ({prov})" if prov else ""), _fmt_closes(r["closes"]), r["ocid"]))
            rows_out = sorted(rows_out, key=lambda x: _closes_date(x[2]) or date.max)
            if rows_out:
                live[trade] = rows_out
    pool = {**FALLBACK, **live}
    return {k: _fresh(v) for k, v in pool.items() if _fresh(v)}

# ─── Email builder ────────────────────────────────────────────────────────────
P="#FFFEFA"; I="#0B0F1C"; I2="#3A3D45"; G="#6B6E76"; Q="#8A8D95"
H="#E7E5DF"; S="#F4F3EF"; B="#024FF5"; F="Inter,'Helvetica Neue',Helvetica,Arial,sans-serif"
LOGO="https://bidcheck.co.za/brand/icon-192.png"
# Inline sender headshots (96px, ~1-2KB each) -- a human face in the signature
# lifts replies; base64 so no external hosting can break the image.
SENDER_PHOTOS = json.loads(r"""{"devan@getbidcheck.co.za": "data:image/jpeg;base64,", "kagiso@getbidcheck.co.za": "data:image/jpeg;base64,", "david@trybidcheck.co.za": "data:image/jpeg;base64,", "nadia@trybidcheck.co.za": "data:image/jpeg;base64,", "lizele@getbidcheck.co.za": "data:image/jpeg;base64,", "gareth@trybidcheck.co.za": "data:image/jpeg;base64,"}""")
NOUNS={"Cleaning":"cleaning","Security":"security","Construction":"construction","Civil":"civil works",
       "Electrical":"electrical","Facilities":"maintenance","ICT":"ICT","Supplies":"supply",
       "Transport":"transport","Catering":"food supply"}
# 2026-10-12: leads imported from Brabys carry slug-style trade labels. Without these entries
# the noun fell back to the raw label and subjects read "Three electrical-contractors tenders".
NOUNS.update({"electrical-contractors":"electrical","plumbing-contractors":"plumbing",
              "training-centres":"training","general-suppliers":"supply",
              "transport-contractors":"transport","Building Maintenance":"building maintenance"})
WORDS={1:"One",2:"Two",3:"Three"}

def ec(s): return str(s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace('"',"&quot;")
_KEEP_UP = {"CCTV","HVAC","ICT","IT","PPE","SA","RSA","VIP","JHB","PTA","CPT","DBN","CIDB","BBBEE","UPS","LED","PA","HR","CNC","SANRAL"}
_SMALL = {"and","the","of","for","to","in","on","at","by","&"}
_PARTICLES = {"DU","DE","LA","LE","VAN","VON","DER","DEN","TER","DA","DOS"}
# 3-letter-or-shorter words that are words, not acronyms (so "BAR DELI" and "TERMITE GUY" stay readable).
_WORDS3 = set("bar guy pro dot com age bat air ex new pet car bus fix job pay hub key one top web way day fit fun gas hot ice joy lab law map net oil pop red sun tax toy van wax zip bid big can eco fly gym hit kid low max mix pin pit rig tip tow use vet wet zoo all out pty ltd inc".split())
def _case_caps(n):
    """ALL-CAPS directory names -> Title Case, keeping real acronyms ("PJ Rubble", "JHB VIP", "CCTV")."""
    out = []
    for i, w in enumerate(n.split()):
        core = re.sub(r"[^A-Za-z&]", "", w)
        lc = core.lower()
        if core.upper() in _KEEP_UP:
            out.append(w.upper())
        elif core.upper() in _PARTICLES:
            out.append(w[:1].upper() + w[1:].lower())
        elif lc in _SMALL and i:
            out.append(w.lower())
        elif len(core) == 1 and core.isalpha():
            out.append(w.upper())                      # initials: "C A Du Toit"
        elif len(core) <= 3 and core.isalpha() and lc not in _WORDS3:
            out.append(w.upper())                      # short unknown token -> acronym (PJ, EBG, ERM)
        else:
            out.append(w[:1].upper() + w[1:].lower())
    return " ".join(out)

def cn(name):
    n = str(name or "").strip()
    n = re.split(r"\s+\|\s+", n)[0]                              # "Brand | tagline"
    m = re.split(r"\s+[-\u2013\u2014]\s+", n, maxsplit=1)         # "Brand - tagline / location"
    if len(m) == 2: n = m[0]
    t = re.search(r"\bt/a\b", n, re.I)
    if t: n = n[t.end():].strip() or n[:t.start()].strip()         # use the trading-as name
    n = re.sub(r"\([^)]*\)", " ", n)                               # every parenthetical, incl. (Pty), (Pty ), (SA)
    n = re.split(r"[,:;]|\s\.", n)[0]                              # stop at the first sentence-like break
    n = re.sub(r"\s+", " ", n).strip(" .-")
    for _ in range(2):                                              # legal suffixes: Ltd, Pty Ltd, Limited, CC, Inc, NPC
        n = re.sub(r"[\s,]*\b(pty\s*)?(ltd|limited)\b\.?$|[\s,]+(cc|c\.c\.|inc|npc|edms bpk)\.?$", "", n, flags=re.I).strip(" .-")
    if n.isupper() and len(n) > 4: n = _case_caps(n)
    return n or str(name or "").strip()

# ─── Plain-note challenger ("L") ──────────────────────────────────────────────────────────────────────────
# The designed email (logo, 25px headline, dark offer panel, photo) is the control. L is a short note that reads like a
# person wrote it: no images, no hidden preheader, 4 links, same one-time / POPIA disclosure and the same "reply yes" offer.
# A/B-eligible leads (not award-based C) are split by a stable hash of the address, so a lead never flips between arms.
# LEAN_PCT=0 in the Railway env switches it off without a deploy.
LEAN_PCT = int(os.environ.get("LEAN_PCT", "80") or 0)
# 2026-10-12: every lead gets exactly one POPIA approach, so most of the pool goes to the format the cold-email playbook
# favours (plain note); 20% keeps the designed email as a measured control.

# Daily send ceiling across every inbox. 989 leads were left on 12 Oct and capacity jumps from ~216/day to ~700+/day once
# the 16 parked AgentMail orgs lift, which would empty the list by Wednesday and leave the sender idle. Raise it in the
# Railway variables when new leads land. 0 = no ceiling.
DAILY_MAX = int(os.environ.get("DAILY_MAX", "260") or 0)
# Runs that start at or after this UTC hour (14:00 UTC = 16:00 SAST) only handle replies: no cold sends after hours.
SEND_UNTIL_UTC_HOUR = int(os.environ.get("SEND_UNTIL_UTC_HOUR", "14") or 14)

def _use_lean(lead):
    if LEAN_PCT <= 0: return False
    if (lead.get("variant") or "A").upper() == "C" and lead.get("award_buyer"): return False
    return int(hashlib.sha1((lead.get("email") or "").lower().encode()).hexdigest()[:8], 16) % 100 < LEAN_PCT

def _variant_for(lead):
    if _use_lean(lead): return "L"
    v = (lead.get("variant") or "A").upper()
    return "C" if (v == "C" and lead.get("award_buyer")) else ("B" if v == "B" else "A")

def _lean_subject(tenders, noun, n):
    """Short, lowercase, internal-looking, no urgency (cold-email playbook). Acronyms stay upper case."""
    return f"{noun if noun.isupper() else noun.lower()} tenders closing soon"

def build_email_lean(lead, tenders, sname, semail):
    import urllib.parse as up
    sname = (sname or "The Bidcheck Team").split(" | ")[0]   # "Kagiso Molefe | Bidcheck" -> "Kagiso Molefe"
    co = cn(lead.get("company", ""))
    tr = lead.get("trade", "ICT")
    noun = NOUNS.get(tr, tr.lower())
    art = "an" if noun[:1].lower() in "aeiou" else "a"
    n = len(tenders); pl = "s" if n > 1 else ""
    dom = (lead.get("domain") or semail.split("@")[1]).split(".")[0][:18]
    _tr = re.sub(r"[^a-z0-9]+", "-", tr.lower()).strip("-"); _dm = re.sub(r"[^a-z0-9]+", "-", dom.lower()).strip("-")
    utm = f"utm_source=cold_email&utm_medium=email&utm_campaign=gp_oct26_l&utm_content={_tr}_{_dm}"
    subj = _lean_subject(tenders, noun, n)
    total = COUNTS.get(tr, 0)
    all_slug = {"Cleaning":"cleaning","Security":"security","Construction":"construction","Civil":"construction","Electrical":"construction",
                "Facilities":"in","ICT":"ict","Supplies":"supplies","Transport":"transport","Catering":"catering","Building Maintenance":"construction"}.get(tr, "in")
    all_l = f"https://bidcheck.co.za/tenders/{all_slug}?{utm}_all"
    tot_txt = f"{total}{'+' if total >= 40 else ''}"
    lede = (f"{tot_txt} {noun} tenders are open on National Treasury eTenders right now. These {n if n > 1 else ''} close soonest:" if total > n
            else f"{WORDS.get(n, str(n))} {noun} tender{pl} {'are' if n > 1 else 'is'} open right now (National Treasury eTenders), soonest closing first:")
    mail = f"mailto:{semail}?subject={up.quote('Yes, fit check for ' + co)}"
    offer = (f'Want to know if {co} qualifies? Reply "yes" and I\'ll send a one-page check on {"these" if n > 1 else "it"}: '
             f'the documents {"each asks" if n > 1 else "it asks"} for, any compulsory briefing, and how to submit. '
             f'Or reply "weekly" and I\'ll email you every new {noun} tender each Monday, free.')
    foot = (f'This is a one-time email. We found {co} as {art} {noun} business and emailed your published address. '
            f'Reply "remove" to stop.')
    rows_h, rows_t = "", []
    for i, (title, buyer, closes, ocid) in enumerate(tenders):
        tl = f"https://bidcheck.co.za/tender/{ocid}?{utm}_t{i + 1}"
        rows_h += (f'<p style="margin:0 0 12px;"><a href="{ec(tl)}" style="color:#024FF5;text-decoration:underline;">{ec(title)}</a><br>'
                   f'<span style="color:#6B6E76;">{ec(buyer)}, closes {ec(closes)}</span></p>')
        rows_t.append(f"- {title}\n  {buyer}, closes {closes}\n  {tl}")
    offer_h = re.sub(r"[Rr]eply &quot;yes&quot;", lambda m_: f'<a href="{ec(mail)}" style="color:#024FF5;">{m_.group(0)}</a>', ec(offer), count=1)
    html = (f'<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
            f'<title>{ec(subj)}</title></head><body style="margin:0;padding:0;background:#ffffff;">'
            f'<div style="max-width:560px;padding:20px 22px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.55;color:#1A1A1A;">'
            f'<p style="margin:0 0 14px;">Hi {ec(co)} team,</p><p style="margin:0 0 14px;">{ec(lede)}</p>{rows_h}'
            f'<p style="margin:4px 0 14px;"><a href="{ec(all_l)}" style="color:#024FF5;">See all {ec(tot_txt)} open {ec(noun)} tenders</a></p>'
            f'<p style="margin:16px 0 18px;">{offer_h}</p>'
            f'<p style="margin:0 0 24px;">{ec(sname)}<br>Bidcheck | bidcheck.co.za</p>'
            f'<p style="margin:0;padding-top:12px;border-top:1px solid #E7E5DF;font-size:12px;line-height:1.5;color:#6B6E76;">{ec(foot)}<br>'
            f'Bidcheck (Pty) Ltd, Cape Town, South Africa</p></div></body></html>')
    text = "\n".join([f"Hi {co} team,", "", lede, ""] + rows_t + ["", f"All {tot_txt} open {noun} tenders: {all_l}", "", offer, "", sname, "Bidcheck | bidcheck.co.za", "", foot,
                                                                      "Bidcheck (Pty) Ltd, Cape Town, South Africa."])
    return subj, html, text

# ─── Reply attribution: which email did this person answer? ───────────────────────────────────────────────
def _infer_variant(subj):
    s = (subj or "").lower()
    if s.startswith("before you bid"): return "B"
    if s.startswith("after your"): return "C"
    if re.match(r"^(one|two|three|\d+) .+ tenders? open in gauteng$", s): return "A"
    if s.endswith("tenders closing soon"): return "L"
    return "L" if (", closes " in s or ", first closes " in s) else "?"

def _variant_index():
    idx = {}
    try:
        for ln in open(STATE_DIR / "sent_log.jsonl"):
            try: r = json.loads(ln)
            except Exception: continue
            idx[(r.get("em") or "").lower()] = (r.get("v") or _infer_variant(r.get("subj")), r.get("trade", ""))
    except Exception:
        pass
    return idx

def _vtag(frm):
    """'  ·  v=L, Security' for a reply from a lead we emailed; '' when unknown. Appended AFTER the existing '[KIND] subject — from'
    text so any filter on the '[YES]' prefix keeps working."""
    m = re.search(r"[\w.+\-]+@[\w.\-]+", frm or "")
    hit = _variant_index().get(m.group(0).lower()) if m else None
    return f"  ·  v={hit[0]}, {hit[1]}" if hit else ""

